import{_ as a,o,c as t,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Personagens e Organizações Chave","description":"","frontmatter":{},"headers":[],"relativePath":"pt/95-关键人物与组织.md","filePath":"pt/95-关键人物与组织.md","lastUpdated":null}'),i={name:"pt/95-关键人物与组织.md"};function r(s,e,n,c,l,u){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="personagens-e-organizacoes-chave" tabindex="-1">Personagens e Organizações Chave <a class="header-anchor" href="#personagens-e-organizacoes-chave" aria-label="Permalink to &quot;Personagens e Organizações Chave&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>95</td></tr><tr><td>Módulo</td><td>Apêndices e Materiais de Referência</td></tr><tr><td>Palavras-chave principais</td><td>personagens chave, organizações importantes, papéis históricos, funções institucionais, civilização de simbiose</td></tr></tbody></table><h2 id="_1-descricao" tabindex="-1">1. Descrição <a class="header-anchor" href="#_1-descricao" aria-label="Permalink to &quot;1. Descrição&quot;">​</a></h2><p>Este documento inclui os personagens chave e organizações importantes no curso de desenvolvimento da Civilização de Simbiose de Âncora, organizados por período histórico e tipo de organização. A parte de personagens chave lista nome do personagem, período, contribuição central e posição histórica; a parte de organizações importantes lista nome da organização, tempo de fundação, função central e papel histórico. Este documento é um documento de atualização dinâmica; com o avanço da história e a evolução das organizações, continuará a ser complementado e revisado.</p><h2 id="_2-personagens-chave" tabindex="-1">2. Personagens Chave <a class="header-anchor" href="#_2-personagens-chave" aria-label="Permalink to &quot;2. Personagens Chave&quot;">​</a></h2><h3 id="_2-1-pioneiros-do-pensamento-na-era-pre-ancora" tabindex="-1">2.1 Pioneiros do Pensamento na Era Pré-Âncora <a class="header-anchor" href="#_2-1-pioneiros-do-pensamento-na-era-pre-ancora" aria-label="Permalink to &quot;2.1 Pioneiros do Pensamento na Era Pré-Âncora&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome do personagem</th><th>Período</th><th>Contribuição central</th><th>Posição histórica</th></tr></thead><tbody><tr><td>Xuan Hengzi</td><td>Cerca de -500 milhões de anos</td><td>Primeiro pensador a refletir sistematicamente sobre o sistema de cultivo de estilo de pilhagem, propôs o protótipo do conceito de &quot;simbiose&quot;, autor do volume fragmentado &quot;Teoria Anti-Pilhagem&quot;</td><td>Pioneiro antigo do pensamento de simbiose, cujo pensamento, após centenas de milhões de anos de sono, tornou-se a fonte espiritual da Civilização de Simbiose de Âncora</td></tr><tr><td>Wan Lingmu</td><td>Cerca de -100 milhões de anos</td><td>Liderou a primeira civilização experimental de simbiose em grande escala; embora finalmente destruída pela civilização de estilo de pilhagem, sua prática provou a viabilidade do sistema de simbiose</td><td>Precursora da prática de simbiose, reverenciada pelas gerações posteriores como a &quot;Mãe da Simbiose&quot;</td></tr><tr><td>Mao Juezhe</td><td>Cerca de -10.000 anos</td><td>Cultivador do primeiro plano, sentiu acidentalmente os nós estáveis na rede de leis durante o cultivo de longo prazo, descobriu o mecanismo de âncora</td><td>Descobridor do mecanismo de âncora, inaugurador da Era do Despertar de Âncora</td></tr></tbody></table><h3 id="_2-2-fundadores-da-era-do-despertar-de-ancora" tabindex="-1">2.2 Fundadores da Era do Despertar de Âncora <a class="header-anchor" href="#_2-2-fundadores-da-era-do-despertar-de-ancora" aria-label="Permalink to &quot;2.2 Fundadores da Era do Despertar de Âncora&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome do personagem</th><th>Período</th><th>Contribuição central</th><th>Posição histórica</th></tr></thead><tbody><tr><td>Mao Dinggong</td><td>-10000 a -9200 anos</td><td>Discípulo de Mao Juezhe, pesquisou sistematicamente o mecanismo de âncora, construiu a primeira âncora artificial, autor de &quot;Princípios de Âncora&quot;</td><td>Fundador da tecnologia de âncora, inventor da âncora artificial</td></tr><tr><td>Gong Shengzi</td><td>-6000 a -5100 anos</td><td>Combinou a tecnologia de âncora com o pensamento de simbiose, criou o sistema teórico de &quot;Simbiose de Âncora&quot;, autor de &quot;Teoria da Simbiose de Âncora&quot;</td><td>Criador da teoria da simbiose de âncora, mentor espiritual da civilização de simbiose</td></tr><tr><td>Heng Yuangong</td><td>-5000 a -4300 anos</td><td>Construiu a primeira cidade-estado de tipo simbiótico baseada em âncora, &quot;Cidade Heng Yuan&quot;, e defendeu com sucesso o ataque da civilização de estilo de pilhagem</td><td>Fundador da primeira cidade-estado de tipo simbiótico, praticante do sistema de simbiose</td></tr><tr><td>Wan Zushi</td><td>-2000 a -1200 anos</td><td>Iniciou a primeira &quot;Conferência de Simbiose de Todas as Raças&quot;, percorreu dezenas de raças defendendo a união simbiótica</td><td>Defensor da união de todas as raças, pioneiro da simbiose inter-racial</td></tr></tbody></table><h3 id="_2-3-fundadores-do-estado-no-periodo-de-estabelecimento-do-sistema-de-simbiose" tabindex="-1">2.3 Fundadores do Estado no Período de Estabelecimento do Sistema de Simbiose <a class="header-anchor" href="#_2-3-fundadores-do-estado-no-periodo-de-estabelecimento-do-sistema-de-simbiose" aria-label="Permalink to &quot;2.3 Fundadores do Estado no Período de Estabelecimento do Sistema de Simbiose&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome do personagem</th><th>Período</th><th>Contribuição central</th><th>Posição histórica</th></tr></thead><tbody><tr><td>Li Xiangong</td><td>-1000 a -900 anos</td><td>Presidente do Comitê de Redação da Constituição de Simbiose, liderou a redação da &quot;Constituição de Simbiose&quot;, promoveu a aprovação da constituição por referendo popular</td><td>Principal redator da Constituição de Simbiose, pai constitucional da civilização de simbiose</td></tr><tr><td>Zhi Fagong</td><td>-900 a -780 anos</td><td>Primeiro presidente do Comitê Executivo de Simbiose, liderou o estabelecimento do sistema administrativo e do mecanismo de execução legal da civilização de simbiose</td><td>Fundador do sistema administrativo de simbiose, primeiro chefe administrativo</td></tr><tr><td>Si Famu</td><td>-900 a -800 anos</td><td>Primeiro juiz presidente do Tribunal de Simbiose, estabeleceu o sistema judicial e o sistema de revisão de inconstitucionalidade da civilização de simbiose</td><td>Fundadora do sistema judicial de simbiose, primeira chefe judicial</td></tr><tr><td>San Baishi</td><td>-500 a -300 anos</td><td>Liderou o trabalho de escavação e organização do sistema de cultivo de origem de trezentos conjuntos, liderou a equipe a concluir a verificação de todos os trezentos conjuntos do sistema</td><td>Organizador geral do sistema de trezentos conjuntos, comandante geral do projeto de abertura de cultivo</td></tr><tr><td>Bei Zenggong</td><td>-300 a -220 anos</td><td>Liderou a pesquisa de aplicação tecnológica do fruto de duplicação, alcançou o avanço de engenharia da tecnologia de amplificação de dedução de cem vezes</td><td>Cientista-chefe da tecnificação do fruto de duplicação, promotor do sistema de iteração de dedução</td></tr></tbody></table><h3 id="_2-4-lideres-no-periodo-de-abertura-e-ativacao" tabindex="-1">2.4 Líderes no Período de Abertura e Ativação <a class="header-anchor" href="#_2-4-lideres-no-periodo-de-abertura-e-ativacao" aria-label="Permalink to &quot;2.4 Líderes no Período de Abertura e Ativação&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome do personagem</th><th>Período</th><th>Contribuição central</th><th>Posição histórica</th></tr></thead><tbody><tr><td>Kai Fanggong</td><td>-100 a -50 anos</td><td>Liderou o trabalho de abertura completa do sistema de cultivo de origem de trezentos conjuntos, estabeleceu o sistema de alocação de recursos de cultivo e a rede de mentores</td><td>Comandante geral da abertura do sistema de trezentos conjuntos, praticante de &quot;todos têm um caminho&quot;</td></tr><tr><td>Ji Huogong</td><td>-50 anos ao ano zero</td><td>Liderou a implementação da estratégia de ativação de 20%, liderou a equipe a concluir a meta de ativação de 20% dos seres em 50 anos</td><td>Comandante geral da estratégia de ativação de 20%, inaugurador da nova era da civilização de simbiose</td></tr><tr><td>Sheng Weigong</td><td>Ano zero a 80 anos</td><td>Liderou o primeiro projeto de elevação dimensional, promoveu a implementação do caminho de elevação dimensional de quatro estágios, alcançou a primeira elevação dimensional em etapas</td><td>Engenheiro-chefe da primeira elevação dimensional, líder da era de elevação dimensional</td></tr></tbody></table><h3 id="_2-5-exploradores-na-era-da-republica-de-todas-as-racas-e-inter-planos" tabindex="-1">2.5 Exploradores na Era da República de Todas as Raças e Inter-planos <a class="header-anchor" href="#_2-5-exploradores-na-era-da-republica-de-todas-as-racas-e-inter-planos" aria-label="Permalink to &quot;2.5 Exploradores na Era da República de Todas as Raças e Inter-planos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome do personagem</th><th>Período</th><th>Contribuição central</th><th>Posição histórica</th></tr></thead><tbody><tr><td>Wan Zu Gongzhu</td><td>100 a 200 anos</td><td>Liderou o trabalho de fundação da República de Todas as Raças, promoveu a compilação do catálogo de todas as raças e a política de fusão inter-racial</td><td>Fundador da República de Todas as Raças, primeiro chefe da República de Todas as Raças</td></tr><tr><td>Wei Mianmu</td><td>500 a 650 anos</td><td>Primeiro diretor da Administração de Gerenciamento de Planos, liderou o plano de exploração inter-planos em grande escala, estabeleceu o banco geral de coordenadas de planos</td><td>Pioneira da exploração inter-planos, fundadora do sistema de gerenciamento de planos</td></tr><tr><td>Kao Gugong</td><td>800 a 950 anos</td><td>Liderou a maturação final do plano de arqueologia remota por espelho de cópia, promoveu a arqueologia inter-planos a entrar na era de escala</td><td>Mestre do plano de arqueologia, fundador da arqueologia inter-planos</td></tr><tr><td>Shi Lügong</td><td>1000 a 1150 anos</td><td>Liderou o avanço da tecnologia de retrocesso no tempo, promoveu o estabelecimento do princípio de &quot;primeiro observar, depois intervir limitadamente&quot;</td><td>Líder da tecnologia de retrocesso no tempo, formulador dos princípios das leis do tempo</td></tr></tbody></table><h2 id="_3-organizacoes-importantes" tabindex="-1">3. Organizações Importantes <a class="header-anchor" href="#_3-organizacoes-importantes" aria-label="Permalink to &quot;3. Organizações Importantes&quot;">​</a></h2><h3 id="_3-1-instituicoes-de-poder-supremo" tabindex="-1">3.1 Instituições de Poder Supremo <a class="header-anchor" href="#_3-1-instituicoes-de-poder-supremo" aria-label="Permalink to &quot;3.1 Instituições de Poder Supremo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da organização</th><th>Tempo de fundação</th><th>Função central</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Conselho de Âncora</td><td>-900 anos</td><td>Instituição de poder supremo da civilização de simbiose, composta por representantes de todas as raças proporcionalmente, exerce poder legislativo e poder de decisão sobre assuntos importantes</td><td>Instituição de decisão suprema da civilização de simbiose, formuladora de todas as leis e estratégias importantes</td></tr><tr><td>Comitê Executivo de Simbiose</td><td>-900 anos</td><td>Instituição administrativa suprema da civilização de simbiose, responsável pela execução da constituição e das leis, governança diária</td><td>Instituição administrativa suprema da civilização de simbiose, executor de leis e políticas</td></tr><tr><td>Tribunal de Simbiose</td><td>-900 anos</td><td>Instituição judicial suprema da civilização de simbiose, exerce independentemente o poder judicial, responsável pela revisão de inconstitucionalidade e pelo julgamento de casos importantes</td><td>Instituição judicial suprema da civilização de simbiose, guardiã do Estado de Direito</td></tr><tr><td>Comitê de Supervisão de Âncora</td><td>-900 anos</td><td>Instituição de supervisão independente, responsável por supervisionar todas as instituições de poder, prevenir o abuso de poder</td><td>Instituição de supervisão independente da civilização de simbiose, elo chave no equilíbrio de poder</td></tr></tbody></table><h3 id="_3-2-instituicoes-de-gerenciamento-especializado" tabindex="-1">3.2 Instituições de Gerenciamento Especializado <a class="header-anchor" href="#_3-2-instituicoes-de-gerenciamento-especializado" aria-label="Permalink to &quot;3.2 Instituições de Gerenciamento Especializado&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da organização</th><th>Tempo de fundação</th><th>Função central</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Administração de Gerenciamento de Planos</td><td>500 anos</td><td>Responsável pela manutenção do banco geral de coordenadas de planos, aprovação de licenças de viagem, gerenciamento de arqueologia inter-planos, coordenação diplomática inter-planos</td><td>Instituição principal da interação inter-planos, gerente da exploração de planos</td></tr><tr><td>Comitê das Leis do Tempo</td><td>1000 anos</td><td>Responsável pela aprovação de operações de retrocesso no tempo, pesquisa das leis do tempo, supervisão da prevenção de paradoxos temporais</td><td>Instituição de aprovação e supervisão de operações de retrocesso no tempo, guardiã da segurança das leis do tempo</td></tr><tr><td>Comitê de Auditoria das Leis do Tempo</td><td>1050 anos</td><td>Responsável pela auditoria posterior das operações de retrocesso no tempo, confirmar que não causou perturbação incontrolável da linha do tempo</td><td>Instituição de auditoria independente de operações temporais, última linha de defesa da segurança de retrocesso no tempo</td></tr><tr><td>Comitê de Ética Inter-planos</td><td>600 anos</td><td>Formula e interpreta os princípios éticos inter-planos, aprova projetos de interação inter-planos de alto risco, recebe reclamações de violações éticas</td><td>Instituição de supervisão ética da interação inter-planos, guardiã da subjetividade civilizacional</td></tr><tr><td>Escritório de Auditoria de Retorno de Conhecimento</td><td>850 anos</td><td>Responsável pela auditoria de operações de retorno de conhecimento, garantir que o conteúdo retornado esteja em conformidade com o princípio de &quot;apenas retornar conhecimento&quot;</td><td>Instituição de auditoria de retorno de conhecimento, elo chave na prevenção de poluição inter-planos</td></tr></tbody></table><h3 id="_3-3-instituicoes-de-pesquisa-e-educacao" tabindex="-1">3.3 Instituições de Pesquisa e Educação <a class="header-anchor" href="#_3-3-instituicoes-de-pesquisa-e-educacao" aria-label="Permalink to &quot;3.3 Instituições de Pesquisa e Educação&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da organização</th><th>Tempo de fundação</th><th>Função central</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Instituto de Pesquisa de Âncora</td><td>-8000 anos</td><td>Pesquisa básica e desenvolvimento de aplicação do mecanismo de âncora, construção e manutenção de âncoras artificiais</td><td>Instituição central de pesquisa da tecnologia de âncora, uma das fontes tecnológicas da civilização de simbiose</td></tr><tr><td>Comitê de Organização do Sistema de Trezentos Conjuntos</td><td>-500 anos</td><td>Escavação, organização, verificação e otimização contínua do sistema de cultivo de origem de trezentos conjuntos</td><td>Instituição de organização e manutenção do sistema de trezentos conjuntos, suporte técnico para a abertura de cultivo</td></tr><tr><td>Liga das Universidades de Simbiose</td><td>-700 anos</td><td>Organização conjunta de educação superior e educação de cultivo, responsável pela formação de talentos avançados e pesquisa acadêmica</td><td>Liga das instituições de ensino superior da civilização de simbiose, núcleo de formação de talentos e inovação acadêmica</td></tr><tr><td>Faculdade de Arqueologia Inter-planos</td><td>550 anos</td><td>Forma profissionais de arqueologia inter-planos, realiza pesquisa de tecnologia arqueológica e inovação metodológica</td><td>Centro de formação de talentos e pesquisa tecnológica de arqueologia inter-planos</td></tr><tr><td>Instituto de Pesquisa das Leis do Tempo</td><td>950 anos</td><td>Pesquisa teórica básica das leis do tempo e pesquisa e desenvolvimento da tecnologia de retrocesso no tempo</td><td>Instituição central de pesquisa das leis do tempo, berço da tecnologia de retrocesso no tempo</td></tr></tbody></table><h3 id="_3-4-organizacoes-militares-e-de-seguranca" tabindex="-1">3.4 Organizações Militares e de Segurança <a class="header-anchor" href="#_3-4-organizacoes-militares-e-de-seguranca" aria-label="Permalink to &quot;3.4 Organizações Militares e de Segurança&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da organização</th><th>Tempo de fundação</th><th>Função central</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Exército de Defesa de Simbiose</td><td>-850 anos</td><td>Força de defesa regular da civilização de simbiose, responsável pela defesa de planos e enfrentamento de ameaças externas</td><td>Principal força militar da civilização de simbiose, defensora da segurança nacional</td></tr><tr><td>Patrulha de Planos</td><td>520 anos</td><td>Responsável pela patrulha e monitoramento de segurança dos planos já explorados, enfrenta incidentes de segurança inter-planos</td><td>Força de primeira linha da segurança inter-planos, mantenedora da ordem dos planos</td></tr><tr><td>Equipe de Emergência de Poluição de Leis</td><td>600 anos</td><td>Responsável pela resposta de emergência e remoção de poluição em incidentes de poluição de leis e poluição de energia</td><td>Força de resposta de emergência de poluição de leis, guardiã do ambiente cósmico</td></tr><tr><td>Grupo de Emergência de Paradoxo Temporal</td><td>1020 anos</td><td>Responsável pela resposta de emergência e operações de reparo causal em incidentes de paradoxo temporal</td><td>Força de resposta de emergência de paradoxo temporal, última garantia da estabilidade da linha do tempo</td></tr></tbody></table><h3 id="_3-5-organizacoes-civis-e-sociais" tabindex="-1">3.5 Organizações Civis e Sociais <a class="header-anchor" href="#_3-5-organizacoes-civis-e-sociais" aria-label="Permalink to &quot;3.5 Organizações Civis e Sociais&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nome da organização</th><th>Tempo de fundação</th><th>Função central</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Conferência de Simbiose de Todas as Raças</td><td>-2000 anos</td><td>Reunião regular de representantes de todas as raças, discute assuntos de simbiose inter-racial, promove intercâmbio cultural</td><td>Plataforma importante para o intercâmbio de todas as raças, organização precursora da República de Todas as Raças</td></tr><tr><td>Associação de Cultivadores</td><td>-600 anos</td><td>Organização de autoadministração profissional dos cultivadores, responsável pela proteção dos direitos dos cultivadores, formulação de normas profissionais</td><td>Organização de autoadministração dos cultivadores, promotora da normatização da indústria de cultivo</td></tr><tr><td>Associação de Consumidores</td><td>-650 anos</td><td>Organização de proteção dos direitos dos consumidores, responsável pela defesa dos direitos dos consumidores, educação do consumidor, supervisão social</td><td>Porta-voz dos direitos dos consumidores, supervisora social da ordem do mercado</td></tr><tr><td>Liga de Proteção Ambiental</td><td>-550 anos</td><td>Organização conjunta civil de proteção ambiental, responsável pela supervisão ambiental, educação ambiental, atividades voluntárias de restauração ecológica</td><td>Força social de proteção ambiental, promotora da civilização ecológica cósmica</td></tr><tr><td>Associação de Amizade Inter-planos</td><td>580 anos</td><td>Organização civil que promove o intercâmbio amigável entre civilizações inter-planos, responsável pela diplomacia civil, intercâmbio cultural</td><td>Força central da diplomacia civil inter-planos, ponte para o entendimento entre civilizações</td></tr></tbody></table><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>Os personagens e organizações chave são os portadores vivos da história da Civilização de Simbiose de Âncora. Dos pioneiros do pensamento antigos aos líderes civilizacionais contemporâneos, das instituições de poder supremo às organizações sociais civis, cada personagem e organização desempenha um papel insubstituível na grande narrativa da civilização de simbiose. Suas lutas e contribuições teceram conjuntamente a épica magnífica da Civilização de Simbiose de Âncora, do nada à existência, do pequeno ao grande, do próprio plano ao universo inteiro.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>70-Tabela Geral da Divisão de Épocas</li><li>49-Estrutura de Governança e Equilíbrio de Poder</li><li>77-Fundação da República de Todas as Raças</li></ul>',30)])])}const h=a(i,[["render",r]]);export{p as __pageData,h as default};
